56	func canUserAccessMentionContext(target *store.User, memo *store.Memo, relatedMemo *store.Memo) bool {
57		if target == nil || memo == nil {
58			return false
59		}
60	
61		if relatedMemo != nil {
62			if relatedMemo.Visibility == store.Private && target.ID != relatedMemo.CreatorID {
63				return false
64			}
65		}
66	
67		if memo.Visibility == store.Private && target.ID != memo.CreatorID {
68			return false
69		}
70	
71		return true
72	}
73	
74	func shouldSkipMentionInbox(target *store.User, memo *store.Memo, relatedMemo *store.Memo) bool {
75		if target == nil || memo == nil {
76			return true
77		}
78	
79		if target.ID == memo.CreatorID {
80			return true
81		}
82	
83		// Comment creation already generates a memo-comment inbox item for the parent creator.
84		if relatedMemo != nil && target.ID == relatedMemo.CreatorID && memo.Visibility != store.Private && memo.CreatorID != relatedMemo.CreatorID {
85			return true
86		}
87	
88		return !canUserAccessMentionContext(target, memo, relatedMemo)
89	}
