91	func (s *APIV1Service) dispatchMemoMentionNotifications(ctx context.Context, memo *store.Memo, relatedMemo *store.Memo, previousContent string) error {
92		if memo == nil {
93			return nil
94		}
95	
96		currentTargets, err := s.resolveMentionTargets(ctx, memo.Content)
97		if err != nil {
98			return err
99		}
100		if len(currentTargets) == 0 {
101			return nil
102		}
103	
104		previousTargets, err := s.resolveMentionTargets(ctx, previousContent)
105		if err != nil {
106			return err
107		}
108	
109		for userID, target := range currentTargets {
110			if _, exists := previousTargets[userID]; exists {
111				continue
112			}
113			if shouldSkipMentionInbox(target, memo, relatedMemo) {
114				continue
115			}
116	
117			payload := &storepb.InboxMessage_MemoMentionPayload{
118				MemoId: memo.ID,
119			}
120			if relatedMemo != nil {
121				payload.RelatedMemoId = relatedMemo.ID
122			}
123	
124			if _, err := s.createInboxWithEmailNotification(ctx, &store.Inbox{
125				SenderID:   memo.CreatorID,
126				ReceiverID: target.ID,
127				Status:     store.UNREAD,
128				Message: &storepb.InboxMessage{
129					Type: storepb.InboxMessage_MEMO_MENTION,
130					Payload: &storepb.InboxMessage_MemoMention{
131						MemoMention: payload,
132					},
133				},
134			}); err != nil {
135				return errors.Wrap(err, "failed to create mention inbox")
136			}
137		}
138	
139		return nil
140	}
141	
142	func (s *APIV1Service) dispatchMemoMentionNotificationsBestEffort(ctx context.Context, memo *store.Memo, relatedMemo *store.Memo, previousContent string) {
143		if err := s.dispatchMemoMentionNotifications(ctx, memo, relatedMemo, previousContent); err != nil {
144			slog.Warn("Failed to dispatch memo mention notifications", slog.Any("err", err), slog.Int64("memo_id", int64(memo.ID)))
145		}
146	}
